// Paste your settings here. This version avoids $env because some self-hosted n8n installs block env access inside Code nodes.
const CONFIG = {
  githubToken: 'PASTE_GITHUB_TOKEN_HERE',
  githubOwner: 'bisco401',
  githubRepo: '6ixo',
  githubBranch: 'main',
  csvPath: 'data/scraped-listings.csv',
  defaultImportStatus: 'pending',
  sources: [
    // Example source. Replace this with the public pages you want to scrape.
    // {
    //   name: 'Tonaton Vehicles',
    //   enabled: true,
    //   list_url: 'https://tonaton.com/c_cars',
    //   base_url: 'https://tonaton.com',
    //   target_surface: 'vehicles',
    //   app_category: 'vehicles',
    //   app_subcategory: 'cars',
    //   rate_limit_seconds: 3,
    //   extractor_config: {
    //     cardPattern: '<a[\\s\\S]*?href="[^"]*car[\\s\\S]*?<\\/a>',
    //     titlePattern: '<h[12][^>]*>([\\s\\S]*?)<\\/h[12]>',
    //     pricePattern: '(GH¢|GHS)\\s?[0-9,.]+',
    //     urlPattern: 'href="([^"]+)"',
    //     imagePattern: '<img[^>]+src="([^"]+)"',
    //     locationPattern: 'Greater Accra[^<]*',
    //     country: 'Ghana'
    //   }
    // }
  ]
};

const OWNER = CONFIG.githubOwner || 'bisco401';
const REPO = CONFIG.githubRepo || '6ixo';
const BRANCH = CONFIG.githubBranch || 'main';
const CSV_PATH = CONFIG.csvPath || 'data/scraped-listings.csv';
const TOKEN = CONFIG.githubToken;
const DEFAULT_STATUS = CONFIG.defaultImportStatus || 'pending';
const SOURCES = CONFIG.sources || [];

if (!TOKEN || TOKEN === 'PASTE_GITHUB_TOKEN_HERE') throw new Error('Paste your GitHub token into CONFIG.githubToken in this Code node.');
if (!Array.isArray(SOURCES) || !SOURCES.length) throw new Error('Add at least one source object to CONFIG.sources in this Code node.');

const csvHeaders = ['id','status','target_surface','app_category','app_subcategory','title','price_text','price_value','currency','city','country','seller','phone','description','image_urls','source_site','source_url','scraped_at','make','model','trim','year','condition','transmission','color','mileage_km','attributes'];
const ghHeaders = { authorization: `Bearer ${TOKEN}`, accept: 'application/vnd.github+json', 'x-github-api-version': '2022-11-28' };
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const strip = (value = '') => String(value || '').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#8373;|&#x20b5;/gi, 'GH¢').replace(/\s+/g, ' ').trim();
const rx = (pattern, flags = 'i') => pattern ? new RegExp(pattern, flags) : null;
const firstMatch = (text, pattern, flags = 'i') => {
  const re = rx(pattern, flags);
  if (!re) return '';
  const match = String(text || '').match(re);
  return strip(match?.[1] || match?.[0] || '');
};
const absUrl = (value, base) => {
  try { return new URL(String(value || ''), base || undefined).toString(); }
  catch { return String(value || '').trim(); }
};
const priceValue = (priceText = '') => {
  const parsed = Number(String(priceText || '').replace(/[^0-9.]/g, ''));
  return Number.isFinite(parsed) ? String(parsed) : '';
};
const currency = (priceText = '') => {
  const text = String(priceText || '');
  if (/GH¢|GHS/i.test(text)) return 'GHS';
  if (/\$/.test(text)) return 'USD';
  if (/£/.test(text)) return 'GBP';
  if (/€/.test(text)) return 'EUR';
  return '';
};
const guessYear = (text = '') => String(String(text || '').match(/\b(19|20)\d{2}\b/)?.[0] || '');
const normalizeCondition = (value = '') => {
  const text = String(value || '').toLowerCase();
  if (/like new/.test(text)) return 'like_new';
  if (/excellent/.test(text)) return 'excellent';
  if (/good/.test(text)) return 'good';
  if (/brand new|\bnew\b/.test(text)) return 'new';
  if (/foreign used|local used|used|pre-owned|preowned/.test(text)) return 'used';
  return '';
};
const csvEscape = (value = '') => {
  const text = String(value ?? '');
  return /[",\n\r]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
};
const parseCsv = (text = '') => {
  const rows = [];
  let row = [];
  let cell = '';
  let quoted = false;
  const pushCell = () => { row.push(cell); cell = ''; };
  const pushRow = () => { pushCell(); if (row.some((v) => String(v || '').trim())) rows.push(row); row = []; };
  const input = String(text || '').replace(/^\uFEFF/, '');
  for (let i = 0; i < input.length; i += 1) {
    const char = input[i];
    const next = input[i + 1];
    if (quoted) {
      if (char === '"' && next === '"') { cell += '"'; i += 1; }
      else if (char === '"') quoted = false;
      else cell += char;
    } else if (char === '"') quoted = true;
    else if (char === ',') pushCell();
    else if (char === '\n') pushRow();
    else if (char !== '\r') cell += char;
  }
  if (cell || row.length) pushRow();
  const headers = (rows.shift() || csvHeaders).map((h) => String(h || '').trim());
  return rows.map((values) => headers.reduce((acc, header, index) => { if (header) acc[header] = values[index] || ''; return acc; }, {}));
};
const toCsv = (rows = []) => [csvHeaders.join(','), ...rows.map((row) => csvHeaders.map((header) => csvEscape(row[header] || '')).join(','))].join('\n') + '\n';
const getGithubCsv = async () => {
  const url = `https://api.github.com/repos/${OWNER}/${REPO}/contents/${encodeURIComponent(CSV_PATH).replace(/%2F/g, '/')}?ref=${BRANCH}`;
  const res = await fetch(url, { headers: ghHeaders });
  if (res.status === 404) return { sha: null, text: csvHeaders.join(',') + '\n' };
  if (!res.ok) throw new Error(`Could not read ${CSV_PATH}: ${res.status} ${await res.text()}`);
  const json = await res.json();
  return { sha: json.sha, text: Buffer.from(json.content || '', 'base64').toString('utf8') };
};
const putGithubCsv = async (text, sha) => {
  const url = `https://api.github.com/repos/${OWNER}/${REPO}/contents/${encodeURIComponent(CSV_PATH).replace(/%2F/g, '/')}`;
  const body = {
    message: 'Update scraped listings CSV',
    branch: BRANCH,
    content: Buffer.from(text, 'utf8').toString('base64'),
    ...(sha ? { sha } : {})
  };
  const res = await fetch(url, { method: 'PUT', headers: { ...ghHeaders, 'content-type': 'application/json' }, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`Could not update ${CSV_PATH}: ${res.status} ${await res.text()}`);
  return await res.json();
};
const extractListings = (source, html) => {
  const config = source.extractor_config || {};
  const base = source.base_url || source.list_url;
  const cardRe = rx(config.cardPattern, 'gi');
  const cards = cardRe ? Array.from(String(html || '').matchAll(cardRe)).map((m) => m[0]) : [html];
  return cards.map((card) => {
    const title = firstMatch(card, config.titlePattern || '<h[12][^>]*>([\\s\\S]*?)<\\/h[12]>', 'i') || firstMatch(card, config.fallbackTitlePattern || 'title="([^"]+)"', 'i');
    const href = firstMatch(card, config.urlPattern || 'href="([^"]+)"', 'i');
    const sourceUrl = absUrl(href || source.list_url, base);
    const priceText = firstMatch(card, config.pricePattern || '(GH¢|GHS|\\$|£|€)\\s?[0-9,.]+', 'i');
    const image = firstMatch(card, config.imagePattern || '<img[^>]+src="([^"]+)"', 'i');
    const location = firstMatch(card, config.locationPattern || '', 'i');
    const description = firstMatch(card, config.descriptionPattern || '', 'i') || strip(card).slice(0, 280);
    const attributes = {
      employmentType: config.employmentType || '',
      experienceLevel: config.experienceLevel || '',
      remote: Boolean(config.remote),
      tags: Array.isArray(config.tags) ? config.tags : []
    };
    const row = {
      id: sourceUrl ? `csv-${Math.abs([...sourceUrl].reduce((a, c) => ((a << 5) - a + c.charCodeAt(0)) | 0, 0))}` : `csv-${Date.now()}`,
      status: source.default_status || DEFAULT_STATUS,
      target_surface: source.target_surface || (source.app_category === 'vehicles' ? 'vehicles' : 'marketplace'),
      app_category: source.app_category || 'electronics',
      app_subcategory: source.app_subcategory || '',
      title,
      price_text: priceText,
      price_value: priceValue(priceText),
      currency: currency(priceText),
      city: config.city || location.split(',')[0]?.trim() || '',
      country: config.country || '',
      seller: firstMatch(card, config.sellerPattern || '', 'i') || config.seller || source.name,
      phone: firstMatch(card, config.phonePattern || '(\\+?\\d[\\d\\s().-]{7,}\\d)', 'i') || config.phone || '',
      description,
      image_urls: image ? absUrl(image, base) : '',
      source_site: source.name || '',
      source_url: sourceUrl,
      scraped_at: new Date().toISOString(),
      make: firstMatch(card, config.makePattern || '', 'i') || config.make || '',
      model: firstMatch(card, config.modelPattern || '', 'i') || config.model || '',
      trim: firstMatch(card, config.trimPattern || '', 'i') || config.trim || '',
      year: firstMatch(card, config.yearPattern || '', 'i') || guessYear(`${title} ${description}`),
      condition: firstMatch(card, config.conditionPattern || '', 'i') || normalizeCondition(`${title} ${description}`),
      transmission: firstMatch(card, config.transmissionPattern || '(Automatic|Manual)', 'i'),
      color: firstMatch(card, config.colorPattern || '', 'i') || config.color || '',
      mileage_km: firstMatch(card, config.mileagePattern || '', 'i'),
      attributes: JSON.stringify(attributes)
    };
    return row;
  }).filter((row) => row.title && row.source_url);
};

const existing = await getGithubCsv();
const rowsByUrl = new Map(parseCsv(existing.text).map((row) => [String(row.source_url || '').trim(), row]));
const summary = [];
for (const source of SOURCES.filter((item) => item && item.enabled !== false)) {
  let fetched = 0;
  let inserted = 0;
  try {
    const delay = Math.max(0, Number(source.rate_limit_seconds || 0)) * 1000;
    if (delay) await sleep(delay);
    const response = await fetch(source.list_url, { headers: { 'user-agent': '6ixo-listing-ingest/1.0 (+https://6ixo.com)' } });
    const html = await response.text();
    if (!response.ok) throw new Error(`Fetch failed: ${response.status}`);
    if (/Just a moment|cf-mitigated|challenges.cloudflare.com/i.test(html)) throw new Error('Blocked by anti-bot challenge. Use API, export, saved public HTML, or screenshot/OCR for this source.');
    const scraped = extractListings(source, html);
    fetched = scraped.length;
    for (const row of scraped) {
      const key = String(row.source_url || '').trim();
      if (!key) continue;
      rowsByUrl.set(key, { ...(rowsByUrl.get(key) || {}), ...row });
      inserted += 1;
    }
    summary.push({ source: source.name, status: 'success', fetched, inserted });
  } catch (error) {
    summary.push({ source: source.name, status: 'failed', fetched, inserted, error: error.message });
  }
}
const nextRows = Array.from(rowsByUrl.values()).sort((a, b) => String(b.scraped_at || '').localeCompare(String(a.scraped_at || '')));
await putGithubCsv(toCsv(nextRows), existing.sha);
return summary.map((row) => ({ json: row }));
